pub fn rsplit(a: Vec<String>, sep: String, maxsplit: u8) -> Vec<Vec<String>> {
    // sep is guaranteed non-empty by the problem statement.
    let limit = maxsplit as usize;

    a.into_iter()
        .map(|s| {
            // If maxsplit == 0, no splitting is performed.
            if limit == 0 {
                return vec![s];
            }

            // For empty input string, result must be a single empty string.
            if s.is_empty() {
                return vec![s];
            }

            let mut parts_rev: Vec<String> = Vec::new();
            let mut remaining: &str = &s;
            let mut splits_done = 0usize;

            while splits_done < limit {
                if let Some(idx) = remaining.rfind(&sep) {
                    let after = idx + sep.len(); // safe: idx is a valid boundary from rfind
                    let right = &remaining[after..];
                    parts_rev.push(right.to_string());
                    remaining = &remaining[..idx];
                    splits_done += 1;
                } else {
                    break;
                }
            }

            // Push the leftover prefix (may be empty).
            parts_rev.push(remaining.to_string());

            // Reverse to restore left-to-right order.
            parts_rev.reverse();
            parts_rev
        })
        .collect()
}